// Jabatan akun dikelola oleh master bersama hak akses, tanpa mengubah modul yang dipilih.
(()=>{
  const setCurrentJobTitle=()=>{
    const user=window.capUser,role=document.querySelector('#currentRole');
    if(!user||!role)return;
    const accountType=user.role==='master'?'Akun master':'Akun pengguna';
    const label=user.job_title?`${accountType} · ${user.job_title}`:accountType;
    if(role.textContent!==label)role.textContent=label;
  };
  const jobTitleField=(value='',className='')=>{
    const label=document.createElement('label');
    label.className=`job-title-field ${className}`.trim();
    label.textContent='Jabatan';
    const input=document.createElement('input');
    input.name='job_title';
    input.maxLength=80;
    input.autocomplete='organization-title';
    input.placeholder='Contoh: Supervisor Gudang';
    input.value=value||'';
    label.append(input);
    return label;
  };
  const enhanceUserDialog=async()=>{
    const dialog=document.querySelector('#userDialog'),createForm=dialog?.querySelector('#createUserForm'),list=dialog?.querySelector('#userList');
    if(!dialog||!createForm||!list)return;
    const formGrid=createForm.querySelector('.form-grid');
    if(formGrid&&!formGrid.querySelector('[name="job_title"]'))formGrid.append(jobTitleField());
    if(dialog.dataset.jobTitlesReady==='1'||!list.children.length)return;
    dialog.dataset.jobTitlesReady='1';
    let users=[];
    try{
      const response=await fetch('/api/auth/users');
      const body=await response.json();
      if(!response.ok)throw new Error(body.error||'Data pengguna tidak tersedia.');
      users=Array.isArray(body.users)?body.users:[];
    }catch{return;}
    for(const user of users){
      const card=[...list.children].find(item=>item.querySelector('strong')?.textContent===user.username);
      if(!card)continue;
      if(user.role==='master'&&card.tagName!=='FORM'){
        const form=document.createElement('form');
        form.className='user-card master-card';
        form.dataset.userForm='';
        form.dataset.userId=String(user.id);
        const title=document.createElement('div');
        title.className='user-card-title';
        const name=document.createElement('strong');name.textContent=user.username;
        const note=document.createElement('small');note.textContent='Akun master · akses seluruh modul';
        title.append(name,note);
        const badge=document.createElement('span');badge.className='account-badge';badge.textContent='Master';
        const actions=document.createElement('div');actions.className='dialog-actions';
        const save=document.createElement('button');save.className='button secondary';save.type='submit';save.textContent='Simpan jabatan';
        actions.append(save);
        form.append(title,badge,jobTitleField(user.job_title,'user-job-title'),actions);
        card.replaceWith(form);
        continue;
      }
      if(card.matches('form[data-user-form]')&&!card.querySelector('[name="job_title"]')){
        const title=card.querySelector('.user-card-title');
        const field=jobTitleField(user.job_title,'user-job-title');
        if(title)title.insertAdjacentElement('afterend',field);else card.prepend(field);
      }
    }
  };
  window.addEventListener('cap-user-ready',setCurrentJobTitle);
  new MutationObserver(()=>{setCurrentJobTitle();enhanceUserDialog();}).observe(document.documentElement,{childList:true,subtree:true});
  setTimeout(()=>{setCurrentJobTitle();enhanceUserDialog();},0);
})();

/* Developer Kit aman untuk AI/pengembang lain, tersedia dari Pemasang Modul. */
(()=>{
  const ensureDeveloperKitControl=()=>{
    const dialog=document.querySelector('#moduleInstallerDialog');
    if(!dialog||dialog.querySelector('#developerKitSection'))return;
    const diagnostic=dialog.querySelector('#downloadDiagnosticButton')?.closest('section');
    if(!diagnostic)return;
    diagnostic.insertAdjacentHTML('beforebegin','<section id="developerKitSection" class="panel"><p class="eyebrow">DEVELOPER KIT</p><h3>Pengembangan dan perbaikan modul</h3><p class="dialog-note">Unduh source, standar kerja, template, dan validator untuk Codex atau AI lain. Kit tidak memuat database, akun, kata sandi, log, maupun data operasional.</p><div class="dialog-actions"><button id="downloadDeveloperKitButton" class="button secondary" type="button">↓ Unduh Developer Kit</button></div></section>');
    dialog.querySelector('#downloadDeveloperKitButton').onclick=async event=>{
      const button=event.currentTarget;button.disabled=true;
      try{
        const response=await fetch('/api/module-installer/developer-kit.zip');
        if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Developer Kit belum dapat dibuat.');}
        const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');
        link.href=url;link.download='CAP-Codex-Module-Developer-Kit.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),0);
      }catch(error){alert(error.message);}finally{button.disabled=false;}
    };
  };
  document.addEventListener('click',event=>{
    if(event.target.closest('#moduleInstallerButton,#globalModuleInstallerButton'))setTimeout(ensureDeveloperKitControl,0);
  },true);
  new MutationObserver(ensureDeveloperKitControl).observe(document.documentElement,{childList:true,subtree:true});
})();

/* Modul WeCom–WeDrive Excel: dipisahkan dari konfigurasi Sinosure. */
(()=>{
  const start=()=>{
    if(document.querySelector('#wecomExcelView'))return;
    const main=document.querySelector('main'),nav=document.querySelector('.sidebar nav'),dashboard=document.querySelector('#dashboardLinks');
    if(!main||!nav||!dashboard)return setTimeout(start,80);
    main.insertAdjacentHTML('beforeend','<section id="wecomExcelView" class="view" hidden><header><div><p class="eyebrow">INTEGRASI TERPISAH</p><h1>WeCom WeDrive Excel</h1><p class="dialog-note">Koneksi WeCom perusahaan ini terpisah dari Sinosure.</p></div></header><section class="panel"><p class="eyebrow">KONEKSI MODUL</p><h2>Pengaturan WeCom perusahaan</h2><p class="dialog-note">Akun master menetapkan satu akun layanan, folder WeDrive, dan penerima notifikasi default. Secret hanya disimpan di server CAP.</p><button class="button" type="button" id="wecomExcelSetup">Atur koneksi WeCom</button></section><section class="panel"><p class="eyebrow">DOKUMEN EXCEL</p><h2>Workbook WeDrive</h2><p class="dialog-note">Setelah koneksi disimpan, pilih workbook untuk dibaca, diubah, dan dipantau pembaruannya.</p></section></section>');
    document.querySelector('#wecomExcelView').insertAdjacentHTML('beforeend','<section class="panel"><p class="eyebrow">PESAN MASSAL</p><h2>Kirim pesan ke kontak WeCom</h2><p class="dialog-note">Kontak dimuat dari direktori perusahaan WeCom. Pilih penerima sebelum mengirim.</p><div class="dialog-actions"><button id="wecomLoadContacts" class="button secondary" type="button">Muat kontak perusahaan</button><button id="wecomSelectAll" class="button ghost" type="button">Pilih semua</button></div><form id="wecomMassMessageForm"><div id="wecomContactList" class="summary-list"><p class="empty-list">Belum ada kontak dimuat.</p></div><label>Pesan<textarea name="message" rows="4" maxlength="1900" required placeholder="Tulis pesan yang akan dikirim."></textarea></label><div class="dialog-actions"><button class="button" type="submit">Kirim ke kontak terpilih</button></div><p id="wecomMassResult" class="dialog-note"></p></form></section>');
    const contactsHost=document.querySelector('#wecomContactList'),resultHost=document.querySelector('#wecomMassResult');
    const loadContacts=async()=>{contactsHost.innerHTML='<p class="dialog-note">Memuat kontak WeCom…</p>';try{const r=await fetch('/api/wecom-excel/contacts'),d=await r.json();if(!r.ok)throw Error(d.error||'Kontak tidak dapat dimuat.');contactsHost.innerHTML=d.contacts.length?d.contacts.map(c=>`<label class="summary-row"><span><strong>${c.name.replace(/[&<>"']/g,'')}</strong><small>${c.user_id}</small></span><input type="checkbox" name="recipient" value="${c.user_id}"></label>`).join(''):'<p class="empty-list">Tidak ada kontak yang dapat diakses aplikasi ini.</p>';}catch(e){contactsHost.innerHTML=`<p class="empty-list">${e.message}</p>`;}};
    document.querySelector('#wecomLoadContacts').onclick=loadContacts;document.querySelector('#wecomSelectAll').onclick=()=>contactsHost.querySelectorAll('[name="recipient"]').forEach(x=>x.checked=true);
    document.querySelector('#wecomMassMessageForm').onsubmit=async e=>{e.preventDefault();const f=e.target,user_ids=[...f.querySelectorAll('[name="recipient"]:checked')].map(x=>x.value);if(!user_ids.length)return resultHost.textContent='Pilih minimal satu kontak.';if(!confirm(`Kirim pesan kepada ${user_ids.length} kontak?`))return;const r=await fetch('/api/wecom-excel/mass-message',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_ids,message:f.elements.message.value})}),d=await r.json();resultHost.textContent=r.ok?`Pesan dikirim ke ${d.total} kontak.`:(d.error||'Pesan gagal dikirim.');};
    const link=document.createElement('a');link.className='nav-item';link.href='#wecom-excel';link.dataset.view='wecom_excel';link.dataset.module='wecom_excel';link.innerHTML='<span>▦</span> WeCom WeDrive Excel';nav.append(link);
    dashboard.insertAdjacentHTML('beforeend','<a class="dashboard-card" href="#wecom-excel" data-module="wecom_excel"><span>▦</span><div><strong>WeCom WeDrive Excel</strong><p>Baca, ubah, dan pantau Excel WeDrive perusahaan.</p></div><b>→</b></a>');
    const show=()=>{document.querySelectorAll('main>.view').forEach(v=>v.hidden=v.id!=='wecomExcelView');document.querySelectorAll('.nav-item[data-view]').forEach(i=>i.classList.toggle('active',i.dataset.view==='wecom_excel'));location.hash='wecom-excel';};
    link.onclick=e=>{e.preventDefault();show()};dashboard.addEventListener('click',e=>{if(e.target.closest('[data-module="wecom_excel"]')){e.preventDefault();show()}});
    const loadStatus=async()=>{const r=await fetch('/api/wecom-excel/settings'),d=await r.json();const b=document.querySelector('#wecomExcelSetup');if(b&&r.ok)b.textContent=d.settings.connected?'✓ WeCom terhubung · ubah koneksi':'Atur koneksi WeCom';};loadStatus();
    document.querySelector('#wecomExcelSetup').onclick=()=>{
      let dialog=document.querySelector('#wecomExcelConfigDialog');
      if(!dialog){document.body.insertAdjacentHTML('beforeend','<dialog id="wecomExcelConfigDialog"><form><div class="dialog-heading"><div><p class="eyebrow">KONEKSI WE COM</p><h2>WeDrive Excel</h2></div></div><div class="form-grid"><label>Corp ID<input name="corp_id" required/></label><label>Secret aplikasi<input name="corp_secret" type="password" required/></label><label>User ID akun layanan<input name="service_user_id" required/></label><label>Space ID WeDrive<input name="space_id" required/></label><label>Folder ID WeDrive<input name="folder_id" required/></label><label>Agent ID notifikasi<input name="agent_id" type="number" required/></label></div><div class="dialog-actions"><button class="button" type="submit">Simpan koneksi</button></div></form></dialog>');dialog=document.querySelector('#wecomExcelConfigDialog');}
      dialog.querySelector('[name="space_id"]').required=false;dialog.querySelector('[name="folder_id"]').required=false;dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,r=await fetch('/api/wecom-excel/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),d=await r.json();if(!r.ok)return alert(d.error||'Koneksi belum tersimpan.');dialog.close();await loadStatus();};dialog.showModal();
    };
    if(location.hash==='#wecom-excel')show();
  };start();
})();

/* Kelola modul aplikasi aktif untuk akun master. */
(()=>{
  const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const ensureApplicationModules=()=>{
    const dialog=document.querySelector('#moduleInstallerDialog');
    if(!dialog||dialog.querySelector('#applicationModulesSection'))return;
    const snapshotSection=dialog.querySelector('#moduleSnapshotRows')?.closest('section');
    if(!snapshotSection)return;
    snapshotSection.insertAdjacentHTML('beforebegin','<section id="applicationModulesSection" class="panel"><p class="eyebrow">MODUL APLIKASI</p><h3>Kelola modul aktif</h3><p class="dialog-note">Daftar ini berisi modul aplikasi seperti Retur Online, Online Shop, Gaji, Keuangan, dan lainnya. Menonaktifkan modul menyembunyikan menu serta memblokir aksesnya; source dan data tetap aman.</p><div id="applicationModuleRows" class="uploads-list"></div></section>');
    const rows=dialog.querySelector('#applicationModuleRows');
    const load=async()=>{
      try{
        const response=await fetch('/api/module-installer/application-modules'),data=await response.json();
        if(!response.ok)throw new Error(data.error||'Daftar modul tidak dapat dimuat.');
        const modules=Array.isArray(data.modules)?data.modules:[];
        rows.innerHTML=modules.length?modules.map(item=>`<div class="summary-row"><span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.module_key)} · ${item.enabled?'Aktif':'Nonaktif'}</small><small>${escapeHtml(item.description)}</small></span><button class="button ${item.enabled?'danger':'secondary'}" type="button" data-application-module="${escapeHtml(item.module_key)}" data-application-enabled="${item.enabled?'1':'0'}">${item.enabled?'Nonaktifkan':'Aktifkan'}</button></div>`).join(''):'<p class="empty-list">Modul aplikasi tidak ditemukan.</p>';
      }catch(error){rows.innerHTML=`<p class="empty-list">${escapeHtml(error.message)}</p>`;}
    };
    rows.onclick=async event=>{
      const button=event.target.closest('[data-application-module]');if(!button)return;
      const moduleId=button.dataset.applicationModule,enabled=button.dataset.applicationEnabled==='1',title=button.closest('.summary-row')?.querySelector('strong')?.textContent||moduleId;
      if(enabled&&!confirm(`Nonaktifkan modul aplikasi ${title}? Menu dan akses modul akan disembunyikan, tetapi source serta data tidak dihapus.`))return;
      const typed=enabled?prompt(`Konfirmasi kedua: ketik persis NONAKTIFKAN ${moduleId}`):'';
      if(enabled&&typed!==`NONAKTIFKAN ${moduleId}`)return alert('Konfirmasi tidak sesuai. Modul tetap aktif.');
      button.disabled=true;
      try{
        const response=await fetch('/api/module-installer/application-modules',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({module_key:moduleId,enabled:!enabled,confirmed:enabled,confirmation_text:typed})}),data=await response.json();
        if(!response.ok)throw new Error(data.error||'Status modul belum dapat disimpan.');
        alert(enabled?`Modul ${title} dinonaktifkan.`:`Modul ${title} diaktifkan.`);location.reload();
      }catch(error){alert(error.message);}finally{button.disabled=false;}
    };
    load();
  };
  document.addEventListener('click',event=>{if(event.target.closest('#moduleInstallerButton,#globalModuleInstallerButton'))setTimeout(ensureApplicationModules,0);},true);
  new MutationObserver(ensureApplicationModules).observe(document.documentElement,{childList:true,subtree:true});
  document.addEventListener('click',event=>{
    if(!event.target.closest('#moduleInstallerButton,#globalModuleInstallerButton'))return;
    setTimeout(async()=>{
      const dialog=$('#moduleInstallerDialog'),history=dialog?.querySelector('#moduleInstallationRows')?.closest('section');
      if(!dialog||!history)return;
      let rows=$('#moduleIntegrityRows');
      if(!rows){history.insertAdjacentHTML('beforebegin','<section class="panel" id="moduleIntegrityPanel"><p class="eyebrow">KELENGKAPAN MODUL</p><h3>Verifikasi berkas terpasang</h3><p class="dialog-note">Pemeriksaan hanya membaca kecocokan file dengan manifest paket.</p><div id="moduleIntegrityRows" class="uploads-list"></div></section>');rows=$('#moduleIntegrityRows');}
      try{const response=await fetch('/api/module-installer/status'),data=await response.json();if(!response.ok)throw new Error(data.error||'Pemeriksaan belum dapat dimuat.');const reports=Array.isArray(data.integrity)?data.integrity:[];rows.innerHTML=reports.length?reports.map(item=>`<div class="summary-row"><span><strong>${esc(item.title||item.module_id)} ${esc(item.version)}</strong><small>${item.expected_files||0} berkas diperiksa</small></span><span class="${item.ok?'status-ok':'status-error'}">${item.ok?'Lengkap':`Kurang: ${(item.missing||[]).concat(item.different||[]).map(esc).join(', ')}`}</span></div>`).join(''):'<p class="empty-list">Belum ada modul aktif untuk diperiksa.</p>';}catch(error){rows.innerHTML=`<p class="empty-list">${esc(error.message)}</p>`;}
    },0);
  },true);
})();
